import{_ as d,C as c,o as t,c as n,a2 as o,b as s,w as a,a as i,E as h,a3 as l}from"./chunks/framework.2af478d7.js";const C=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),u={name:"architecture.md"};function p(f,e,b,m,g,y){const r=c("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>A request for a content page passes through one route, one controller and a small stack of services that fetch, cache and map Drupal&#39;s JSON:API into an <a href="./vocabulary#entity">Entity</a> for your view. This page shows that path and where you can step in.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Know the <a href="./vocabulary#descriptor">descriptor</a> and the <a href="./vocabulary#source">Source</a> terms. The <a href="./quick-start">Quick start</a> shows the result; this page explains how it works.</p><h2 id="the-request-path" tabindex="-1">The request path <a class="header-anchor" href="#the-request-path" aria-label="Permalink to &quot;The request path&quot;">​</a></h2><p>An item page is served in five steps. The diagram follows one request for <code>/talk/dune</code>, the item route of the <code>talk</code> content type.</p>',6)),(t(),s(l,null,{default:a(()=>[h(r,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20LR%0A%20%20Route%5B%22Laravel%20route%22%5D%20--%3E%20Controller%5B%22ContentItemController%22%5D%0A%20%20Controller%20--%3E%20Fetcher%5B%22ContentFetcher%22%5D%0A%20%20Fetcher%20--%3E%20Manager%5B%22DrupalManager%22%5D%0A%20%20Manager%20--%3E%20Cached%5B%22CachedDrupal%22%5D%0A%20%20Cached%20--%3E%7Cmiss%20or%20stale%7C%20Client%5B%22DrupalClient%22%5D%0A%20%20Client%20--%3E%20Drupal%5B%22Drupal%20JSON%3AAPI%22%5D%0A%20%20Fetcher%20--%3E%20Mapper%5B%22ContentMapper%22%5D%0A%20%20Mapper%20--%3E%20Entity%5B%22Entity%22%5D%0A%20%20Controller%20--%3E%20View%5B%22Blade%20view%22%5D%0A%20%20Entity%20--%3E%20View%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<ol><li><strong>Route.</strong> The package registers the route from your descriptor. The route carries the content type key, so the controller needs no configuration.</li><li><strong>Controller.</strong> <code>ContentItemController</code> asks <code>ContentFetcher</code> for the item and renders the first view that exists in the <a href="./views-and-overrides">view chain</a>.</li><li><strong>Fetcher.</strong> <code>ContentFetcher</code> takes the Source of the content type from <code>DrupalManager</code>, resolves the URL alias to a Drupal resource, then fetches that resource with the <code>include</code> paths of the content type.</li><li><strong>Cache and client.</strong> <code>CachedDrupal</code> answers from Laravel&#39;s cache when it can. Otherwise <code>DrupalClient</code> calls Drupal. See the <a href="./caching-model">Caching model</a>.</li><li><strong>Mapper.</strong> <code>ContentMapper</code> turns the JSON:API document into an <code>Entity</code> whose properties carry your field and relation names. Your view receives it as <code>$entity</code> and under the content type key (<code>$talk</code>).</li></ol><p>Listings differ in one respect: <code>ContentListingController</code> fetches nothing. It renders a view that hosts the <code>drupal::listing</code> Livewire component, and the component calls <code>ContentFetcher</code> for each page. Search follows its own path, described in <a href="./search-setup">Search setup</a>.</p><h2 id="the-building-blocks" tabindex="-1">The building blocks <a class="header-anchor" href="#the-building-blocks" aria-label="Permalink to &quot;The building blocks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Role</th></tr></thead><tbody><tr><td><code>Descriptor</code></td><td>The validated, immutable form of <code>config/drupal-backend.php</code>. Everything else reads from it.</td></tr><tr><td><code>DrupalManager</code></td><td>Hands out one <code>CachedDrupal</code> per Source and flushes Sources.</td></tr><tr><td><code>CachedDrupal</code></td><td>Caches decoded JSON:API documents for one Source. It never caches models.</td></tr><tr><td><code>DrupalClient</code></td><td>Sends HTTP requests to one Drupal site, with timeouts and retries.</td></tr><tr><td><code>ContentFetcher</code></td><td>Fetches items, listing pages and filter options for any content type.</td></tr><tr><td><code>ContentMapper</code></td><td>Maps a JSON:API document to an <code>Entity</code>.</td></tr><tr><td><code>SearchFetcher</code></td><td>Plans every tab through the bound <code>SearchBackend</code> and sends one batch.</td></tr><tr><td><code>SearchBackend</code></td><td>The search seam. The default, <code>NativeSearchBackend</code>, answers from native collections.</td></tr><tr><td><code>RelatedContent</code></td><td>Validates a <code>RelatedRequest</code> and asks the bound <code>RelatedStrategy</code>.</td></tr></tbody></table><p>The container binds <code>Descriptor</code>, <code>DrupalManager</code>, <code>CachedDrupal</code>, <code>DrupalClient</code> and <code>ContentMapper</code> as singletons, and <code>SearchBackend</code> and <code>RelatedStrategy</code> to their native implementations. The value objects of the seams (<code>TabSearch</code>, <code>TabPlan</code>, <code>TabResult</code>, <code>Capabilities</code>, <code>RelatedRequest</code>, <code>Criterion</code>) are <code>final readonly</code> and stable, so an extension can rely on them. <code>CachedDrupal</code> and <code>DrupalClient</code> resolve to the default Source, so code that names no Source gets that one. Inject <code>ContentFetcher</code> in your own controllers to fetch content without the package&#39;s routes.</p><h2 id="how-the-package-boots" tabindex="-1">How the package boots <a class="header-anchor" href="#how-the-package-boots" aria-label="Permalink to &quot;How the package boots&quot;">​</a></h2><ol><li><code>register()</code> merges the package&#39;s default config under yours and binds the services above.</li><li><code>boot()</code> registers the <code>drupal</code> view, Livewire and Blade component namespaces, and the three Artisan commands when the app runs in the console.</li><li>When <code>content_types</code> is not empty, the descriptor is built and validated. This is the moment a broken descriptor fails.</li><li>The package defines three rate limiters (<code>content</code>, <code>search-suggest</code>, <code>drupal-webhook</code>) and registers its routes. Content routes are skipped when <code>routes.auto</code> is <code>false</code>; call <code>Route::drupalContent()</code> where you want them instead. The webhook route never joins the <code>web</code> middleware group, so it has no session and no CSRF check.</li></ol><p>With no content types, the package does none of steps 3 and 4.</p><h2 id="where-you-can-step-in" tabindex="-1">Where you can step in <a class="header-anchor" href="#where-you-can-step-in" aria-label="Permalink to &quot;Where you can step in&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Extension point</th><th>Use it to</th></tr></thead><tbody><tr><td>View overrides</td><td>Replace any default view. See <a href="./views-and-overrides">Views and overrides</a>.</td></tr><tr><td><code>Entity</code> subclass</td><td>Add presentation helpers to a content type. Set it as <code>entity</code> in the descriptor.</td></tr><tr><td><code>SearchBackend</code></td><td>Rebind or <code>extend()</code> it to change how each search tab is answered. <code>plan(TabSearch)</code> returns the tab&#39;s requests and how to read their responses; <code>capabilities()</code> says what it can do. <code>SearchFetcher</code> stays concrete and sends every plan as one concurrent batch. See <a href="./search-setup">Search setup</a>.</td></tr><tr><td><code>RelatedStrategy</code></td><td>Rebind or <code>extend()</code> it to change how related items are chosen. <code>RelatedContent</code> validates the request, then calls it. See <a href="./related-content">Related content</a>.</td></tr><tr><td><code>BackendCheck</code></td><td>Tag a class <code>drupal-backend.checks</code> to add a live check to <code>drupal:validate</code>, run once per Source.</td></tr><tr><td><code>ContractContributor</code></td><td>Tag a class <code>drupal-backend.contract</code> to add modules, per-type lines or sections to <code>drupal:contract</code>.</td></tr><tr><td><code>Route::drupalContent()</code></td><td>Place the content routes yourself, for example inside your own middleware group.</td></tr><tr><td><code>RateLimiter::for()</code></td><td>Redefine one of the three rate limiters after the package boots.</td></tr><tr><td><code>FakesDrupal</code></td><td>Build JSON:API documents for tests. See <a href="./testing">Testing</a>.</td></tr></tbody></table><h2 id="when-drupal-fails" tabindex="-1">When Drupal fails <a class="header-anchor" href="#when-drupal-fails" aria-label="Permalink to &quot;When Drupal fails&quot;">​</a></h2><p>Every failure becomes one of three exceptions, all extending <code>DrupalException</code>. Each renders your <code>errors.{status}</code> view first, then the package&#39;s <code>drupal::error</code>. The outcomes are defined in the <a href="./vocabulary#failures">Vocabulary</a>.</p><table tabindex="0"><thead><tr><th>Exception</th><th>Status</th></tr></thead><tbody><tr><td><code>DrupalNotFound</code></td><td>404</td></tr><tr><td><code>DrupalUnavailable</code></td><td>503 with <code>Retry-After: 30</code></td></tr><tr><td><code>DrupalBadResponse</code></td><td>502</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Learn how responses stay fresh in the <a href="./caching-model">Caching model</a>.</li><li>Declare your content in <a href="./mapping-content">Mapping content</a>.</li><li>Install the package with <a href="./installation">Installation</a>.</li></ul>',15))])}const k=d(u,[["render",p]]);export{C as __pageData,k as default};
